import * as T from './vendor/three.module.js';
// Material-preserving static batching. Animated people and instanced shingles stay intact.
export function mergeStaticChildren(parent){const buckets=new Map();for(const o of [...parent.children]){if(!o.isMesh||o.isInstancedMesh||Array.isArray(o.material))continue;o.updateMatrix();const k=o.material.uuid+':'+o.castShadow+':'+o.receiveShadow;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(o);}
 for(const objects of buckets.values()){if(objects.length<2)continue;const positions=[],normals=[],uv=[],indices=[];let offset=0;for(const o of objects){const g=o.geometry.clone().applyMatrix4(o.matrix),p=g.attributes.position,n=g.attributes.normal,u=g.attributes.uv;for(let i=0;i<p.count;i++){positions.push(p.getX(i),p.getY(i),p.getZ(i));normals.push(n?.getX(i)??0,n?.getY(i)??1,n?.getZ(i)??0);uv.push(u?.getX(i)??0,u?.getY(i)??0);}for(let i=0;i<(g.index?.count??p.count);i++)indices.push(offset+(g.index?.getX(i)??i));offset+=p.count;g.dispose();parent.remove(o);o.geometry.dispose();}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('normal',new T.Float32BufferAttribute(normals,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeBoundingSphere();const mesh=new T.Mesh(g,objects[0].material);mesh.castShadow=objects[0].castShadow;mesh.receiveShadow=objects[0].receiveShadow;mesh.userData.kind='batched-static-chalet-details';parent.add(mesh);}
}
